function showToast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)}
function dateParts(d){const x=new Date(String(d).replace(' ','T'));return isNaN(x)?{d:'--',h:'--',m:'--',s:'--'}:{d:Math.max(0,Math.floor((x-Date.now())/86400000)),h:Math.max(0,Math.floor((x-Date.now())/3600000)%24),m:Math.max(0,Math.floor((x-Date.now())/60000)%60),s:Math.max(0,Math.floor((x-Date.now())/1000)%60)}}
function card(t){const p=Math.max(0,Number(t.capacity)-Number(t.joined||0)),x=dateParts(t.departure_at);return `<article class="trip reveal"><div class="tripImg" style="background-image:url('${esc(t.image_url||destinations[0].img)}')"><span class="pill">${esc(t.destination)}</span><span class="spots">${p} spaces left</span></div><div class="tripBody"><div class="destination">${esc(t.organizer_name||'Trip organizer')}</div><h3>${esc(t.title)}</h3><div class="meta"><span>📅 ${esc(new Date(String(t.departure_at).replace(' ','T')).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}))}</span><span>👥 ${esc(t.capacity)} max</span></div><p class="desc">${esc(t.description)}</p><div class="count"><div class="time"><b>${x.d}</b><span>days</span></div><div class="time"><b>${x.h}</b><span>hours</span></div><div class="time"><b>${x.m}</b><span>min</span></div><div class="time"><b>${x.s}</b><span>sec</span></div></div><div class="tripActions"><button class="btn" onclick="openJoin(${Number(t.id)})">Join this trip</button><button class="mini" onclick="shareTrip(${Number(t.id)})" title="Share">↗</button></div></div></article>`}
function render(){const q=document.getElementById('search').value.trim().toLowerCase();let list=trips.filter(t=>(`${t.title} ${t.destination} ${t.description}`.toLowerCase()).includes(q));if(document.getElementById('sort').value==='far')list.reverse();document.getElementById('tripGrid').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><b>No matching trips.</b><br>Try another destination or create the first one.</div>`;requestAnimationFrame(()=>document.querySelectorAll('.reveal').forEach(e=>observer.observe(e)))}
async function loadTrips(){if(!DB_READY){trips=fallback;render();updateHero();return}try{const r=await fetch('api.php?action=list',{cache:'no-store'});const j=await r.json();if(!j.ok)throw Error(j.error);trips=j.trips||[];render();updateHero()}catch(e){trips=fallback;render();updateHero();showToast('Trip board is in demo mode until the database is configured.')}}
function updateHero(){const t=trips[0];if(!t){document.getElementById('heroTrip').textContent='Your next adventure';document.getElementById('heroDestination').textContent='Create the first trip on the platform.';return}document.getElementById('heroTrip').textContent=t.title;document.getElementById('heroDestination').textContent=t.destination+' · '+(t.organizer_name||'Community organizer');const x=dateParts(t.departure_at);document.getElementById('heroDays').textContent=x.d;document.getElementById('heroHours').textContent=x.h;document.getElementById('heroSpots').textContent=Math.max(0,Number(t.capacity)-Number(t.joined||0))}
function openJoin(id){const t=trips.find(x=>Number(x.id)===Number(id));if(!t)return;document.getElementById('joinId').value=t.id;document.getElementById('joinTitle').textContent='Join '+t.title;openModal('joinModal')}
async function shareTrip(id){const t=trips.find(x=>Number(x.id)===Number(id));if(!t)return;const text=`${t.title} — ${t.destination}`;try{await navigator.clipboard.writeText(location.href+'#trips');showToast('Trip link copied — '+text)}catch{showToast(text)}}
document.getElementById('joinForm').addEventListener('submit',async e=>{e.preventDefault();if(!DB_READY){showToast('Open setup.php and connect the database first.');return}const b=new URLSearchParams({trip_id:document.getElementById('joinId').value,name:document.getElementById('jname').value,phone:document.getElementById('jphone').value,email:document.getElementById('jemail').value,people:document.getElementById('jpeople').value,message:document.getElementById('jmessage').value});try{const r=await fetch('api.php?action=join',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:b});const j=await r.json();if(!j.ok)throw Error(j.error);closeModal('joinModal');e.target.reset();showToast('✓ Registration confirmed. Welcome to the trip!');loadTrips()}catch(err){showToast(err.message||'Could not register.')}});
document.getElementById('createForm').addEventListener('submit',async e=>{e.preventDefault();if(!DB_READY){showToast('Open setup.php and connect the database first.');return}const b=new URLSearchParams({title:document.getElementById('ctitle').value,destination:document.getElementById('cdestination').value,departure:document.getElementById('cdate').value,capacity:document.getElementById('ccapacity').value,organizer:document.getElementById('corganizer').value,phone:document.getElementById('cphone').value,description:document.getElementById('cdescription').value,image:document.getElementById('cimage').value});try{const r=await fetch('api.php?action=create',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:b});const j=await r.json();if(!j.ok)throw Error(j.error);closeModal('createModal');e.target.reset();showToast('✓ Trip published. Refreshing the live board...');await loadTrips();document.getElementById('trips').scrollIntoView({behavior:'smooth'})}catch(err){showToast(err.message||'Could not publish trip.')}});
document.getElementById('search').addEventListener('input',render);document.getElementById('sort').addEventListener('change',render);
function renderDestinations(){const f=destinations[0];document.getElementById('featuredDest').style.backgroundImage=`url('${f.img}')`;document.getElementById('featureTitle').textContent=f.name;document.getElementById('featureText').textContent=f.text;document.getElementById('destSide').innerHTML=destinations.slice(1).map(d=>`<div class="dest" style="background-image:url('${d.img}')"><span>${esc(d.name)}</span></div>`).join('');document.getElementById('marquee').innerHTML=[...destinations,...destinations].map(d=>`<span>✦ ${esc(d.name)}</span>`).join('')}
let destIndex=0;setInterval(()=>{destIndex=(destIndex+1)%destinations.length;const d=destinations[destIndex];document.getElementById('featuredDest').style.backgroundImage=`url('${d.img}')`;document.getElementById('featureTitle').textContent=d.name;document.getElementById('featureText').textContent=d.text},5000);
setInterval(()=>{if(trips.length){updateHero();render()}},1000);
document.getElementById('theme').addEventListener('click',()=>{const dark=document.body.dataset.theme==='dark';document.body.dataset.theme=dark?'':'dark';document.body.style.setProperty('--bg',dark?'#f7faf8':'#0b1510');document.body.style.setProperty('--surface',dark?'#fff':'#132019');document.body.style.setProperty('--ink',dark?'#102018':'#edf7f0');document.body.style.setProperty('--muted',dark?'#65756d':'#a8b8af');document.body.style.setProperty('--line',dark?'#dce7e0':'#30443a');document.getElementById('theme').textContent=dark?'☾':'☀'})
document.getElementById('hamb').addEventListener('click',()=>{const m=document.getElementById('mobileMenu');m.style.display=m.style.display==='block'?'none':'block'});
document.querySelectorAll('.mobileMenu a').forEach(a=>a.addEventListener('click',()=>document.getElementById('mobileMenu').style.display='none'));
window.addEventListener('click',e=>{if(e.target.classList.contains('modal')){e.target.classList.remove('show');document.body.style.overflow=''}});
const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('on')}),{threshold:.08});
renderDestinations();loadTrips();document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
</script></body></html>